const email = $json;

// Fecha y hora del correo en formato SQL Server
const fechaCorreo = new Date(Number(email.internalDate));

const fechaEmail = fechaCorreo.toLocaleString(
  'sv-SE',
  {
    timeZone: 'America/Argentina/Buenos_Aires'
  }
);

// --------------------
// Datos básicos
// --------------------
const subject = (
  email.Subject ||
  email.subject ||
  ""
).toLowerCase();

const sender = (
  email.From ||
  email.from ||
  ""
).toLowerCase();

const labels = (
  email.labels || []
).map(label =>
  (label.name || "").toUpperCase()
);

// --------------------
// Labels de Gmail
// --------------------
const blockedLabels = [
  "CATEGORY_PROMOTIONS",
  "SPAM"
];

const foundLabel = blockedLabels.find(label =>
  labels.includes(label)
);

if (foundLabel) {
  return [{
    ...email,
    fecha_email: fechaEmail,
    procesar: false,
    motivo: `gmail_label:${foundLabel}`
  }];
}

// --------------------
// Remitentes
// --------------------
const blockedSenders = [
  "noreply@",
  "no-reply@",
  "newsletter",
  "marketing",
  "promociones",
  "ofertas",
  "sales@",
  "ventas@"
];

const foundSender = blockedSenders.find(term =>
  sender.includes(term)
);

if (foundSender) {
  return [{
    ...email,
    fecha_email: fechaEmail,
    procesar: false,
    motivo: `sender:${foundSender}`
  }];
}

// --------------------
// Palabras del asunto
// --------------------
const blockedSubjects = [
  "te actualizamos",
  "novedades",
  "suscríbete",
  "newsletter",
  "oferta",
  "promoción",
  "descuento",
  "nuevo producto",
  "black friday",
  "cyber monday"
];

const foundSubject = blockedSubjects.find(term =>
  subject.includes(term)
);

if (foundSubject) {
  return [{
    ...email,
    fecha_email: fechaEmail,
    procesar: false,
    motivo: `subject:${foundSubject}`
  }];
}

// --------------------
// Correo válido
// --------------------
return [{
  ...email,
  fecha_email: fechaEmail,
  procesar: true,
  motivo: "ok"
}];
